# REDACTED DERIVATIVE, generated by paper/make_release_tree.py.
# The private canonical file is NOT released and was NOT modified.
# Speaker names are pseudonymised; private roots are masked to
# <PRIVATE_SOURCE_ROOT> etc. Set them locally to re-run.
# Source sha256: 33437c1753f7e082209f11e82d7ef3809aa33a4e9445288a7a3ea8d0fb234404
r"""Q5 STEP 6 — aggregation, intervals and the SECTION 8 labels.

Reads Q5_CELLS.jsonl, Q5_EMBEDDINGS.npz and Q5_CALIBRATION.json. Writes
Q5_RESULTS.json. Computes nothing from audio and opens no WAV.

Per (arm, encoder, set, stratum):

  R    median of cos(src, recon)              - cluster bootstrap over recordings
  D    median of cos(recon_i, recon_j)        - same speaker, i != j, SECTION 3 rules
  C    from Q5_CALIBRATION.json, matched strictly on (encoder, set, stratum)
  F_hi from Q5_CALIBRATION.json, same state; for CROSS, the max over that set's states

SECTION 8.4 rules, in order, on intervals only:
  1 DRIFTING              D.hi < C.lo                (+ APPROACHES IMPOSTOR RANGE
                                                       iff D.lo <= F_hi)
  2 PRESERVED+CONSISTENT  D.lo >= C.lo and R.lo >= C.lo
  3 STABLE OFFSET         D.lo >= C.lo and R.hi <  C.lo
  4 NOT ESTABLISHED       anything else, with the reason recorded

CROSS strata carry the dispersion-only vocabulary of SECTION 8.1. A DEMOTED
encoder produces every number and NO label. SECTION 7's streamed detector is
computed here too, and never enters a label.
"""
from __future__ import annotations

import argparse
import collections
import json
import os
import time

import numpy as np

import q5_lib as Q

CELLS = os.path.join(Q.HERE, "Q5_CELLS.jsonl")
CACHE = os.path.join(Q.HERE, "Q5_EMBEDDINGS.npz")
CAL = os.path.join(Q.HERE, "Q5_CALIBRATION.json")
OUT = os.path.join(Q.HERE, "Q5_RESULTS.json")


def load_rows():
    rows = []
    for line in open(CELLS, encoding="utf-8"):
        if line.strip():
            rows.append(json.loads(line))
    return rows


def length_states():
    """SECTION 10.2 (revision 4): read the covariate from EVERY Stage 1 file.

    Revision 3's runner read only `gate4_stage1_decbench.jsonl`, so
    `fish_modified_dac` rows carry `NOT RECORDED`. The frozen rows are NOT
    rewritten - the value is looked up here and the lookup is recorded.
    """
    out, files = {}, []
    d = os.path.join(Q.HERE, "results")
    for fn in sorted(os.listdir(d)):
        if not fn.startswith("gate4_stage1") or not fn.endswith(".jsonl"):
            continue
        files.append(fn)
        for line in open(os.path.join(d, fn), encoding="utf-8"):
            if not line.strip():
                continue
            try:
                r = json.loads(line)
            except Exception:
                continue
            if "key" in r and "offline_length_state" in r:
                out[r["key"]] = r["offline_length_state"]
    return out, files


def label_cells(rows, setname):
    """SECTION 8.1 (revision 4): selection is BY SET, never by rung presence.

    Set S -> its own cells. Set L -> the 14 s top-rung cell, one per recording.
    L_ladder sub-rungs carry no label and feed only the duration analysis.
    """
    return [r for r in rows if r["set"] == setname]


def c_ref(cal, enc, setname, stratum):
    """SECTION 8.2: strict matching. No substitution."""
    blk = cal["calibration"][enc]["sets"].get(setname)
    if not blk:
        return None, None
    if stratum == "CROSS":
        c = (blk.get("cross") or {}).get("C_cross")
        fs = [v["F_src"]["p95"] for v in blk["states"].values()
              if isinstance(v, dict) and "p95" in (v.get("F_src") or {})]
        return c, (max(fs) if fs else None)
    v = blk["states"].get(stratum)
    if not isinstance(v, dict) or "C_within" not in v:
        return None, None
    return v["C_within"], (v.get("F_src") or {}).get("p95")


def label(R, D, C, F_hi, stratum, detector_only):
    if detector_only:
        return "NOT ESTABLISHED", "ENCODER DEMOTED TO DETECTOR (SECTION 9.3)", None
    for name, obj in (("C", C), ("D", D)):
        if not obj or "lo" not in obj:
            return ("NOT ESTABLISHED",
                    "%s INTERVAL REFUSED: %s" % (name, (obj or {}).get(
                        "refused", "UNAVAILABLE")), None)
    marker = None
    if F_hi is not None and D["lo"] <= F_hi:
        marker = "APPROACHES IMPOSTOR RANGE"
    if D["hi"] < C["lo"]:
        return (("CROSS-STATE DRIFTING" if stratum == "CROSS"
                 else "INCONSISTENT / DRIFTING"), "D.hi < C.lo", marker)
    if D["lo"] >= C["lo"]:
        if stratum == "CROSS":
            return "CROSS-STATE CONSISTENT", "D.lo >= C.lo", marker
        if not R or "lo" not in R:
            return ("NOT ESTABLISHED", "R INTERVAL REFUSED: %s"
                    % (R or {}).get("refused", "UNAVAILABLE"), marker)
        if R["lo"] >= C["lo"]:
            return "PRESERVED + CONSISTENT", "D.lo >= C.lo and R.lo >= C.lo", marker
        if R["hi"] < C["lo"]:
            return "STABLE OFFSET", "D.lo >= C.lo and R.hi < C.lo", marker
        return ("NOT ESTABLISHED",
                "dispersion resolved but R straddles C.lo", marker)
    return ("NOT ESTABLISHED", "D interval overlaps C.lo (no rule fires)", marker)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--force", action="store_true")
    a = ap.parse_args()
    if os.path.exists(OUT) and not a.force:
        print("REFUSED: %s exists. --force to recompute." % os.path.basename(OUT))
        return 2
    rev = Q.spec_revision()
    cal = json.load(open(CAL, encoding="utf-8"))
    rows = load_rows()
    with np.load(CACHE) as z:
        emb = {k: z[k] for k in z.files}
    print("rows=%d  embeddings=%d" % (len(rows), len(emb)))

    off = [r for r in rows if r["condition"] == "offline"]
    res = {"what": "Q5 identity retention and reconstruction dispersion, per "
                   "encoder, never merged. mcd remains Gate 4's only ranking "
                   "metric; Q5 ranks nothing.",
           "spec": rev,
           "generated_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
           "calibration_source": os.path.basename(CAL),
           "arms": {}, "streaming_detector": {}, "counts": {}}

    cnt = collections.Counter(r["cell_state"] for r in rows)
    res["counts"]["cell_states"] = dict(cnt)

    arms = sorted({r["arm"] for r in off})
    encs = sorted({r["encoder"] for r in off})
    for arm in arms:
        res["arms"][arm] = {}
        for e in encs:
            sel_e = [r for r in off if r["arm"] == arm and r["encoder"] == e]
            det = bool(sel_e and sel_e[0].get("detector_only"))
            res["arms"][arm][e] = {"sets": {}}
            for setname in ("S", "L"):
                states = Q.STATES_S if setname == "S" else Q.STATES_L
                blk = {}
                for stratum in list(states) + ["CROSS"]:
                    base = label_cells(sel_e, setname)
                    if stratum == "CROSS":
                        sel = base
                    else:
                        sel = [r for r in base if r["state"] == stratum]
                    ok = [r for r in sel if r["cell_state"] == Q.MEASURED
                          and r["R"] is not None]
                    # SECTION 8.1: every cell of the chosen set is a label cell -
                    # one per recording by construction (Set S: no rung; Set L:
                    # the single 14 s top rung). L_ladder never reaches here.
                    plain = ok
                    Rb = Q.boot_recording_median(
                        [r["R"] for r in plain],
                        [(r["speaker"], r["state"]) for r in plain],
                        [(r["speaker"], r["state"], r["index"]) for r in plain])
                    # ---- D: pairwise over reconstructions, SECTION 3 rules
                    items = [r for r in plain if r["rec_emb_key"] in emb]
                    Db = {"refused": "NO ADMISSIBLE ITEMS"}
                    if len(items) >= Q.MIN_RECORDINGS:
                        A = np.stack([emb[r["rec_emb_key"]] for r in items]
                                     ).astype(np.float64)
                        M = A @ A.T
                        spk = np.array([r["speaker"] for r in items])
                        stt = np.array([r["state"] for r in items])
                        txt = np.array([r["index"] for r in items])
                        same_spk = spk[:, None] == spk[None, :]
                        diff_txt = txt[:, None] != txt[None, :]
                        if stratum == "CROSS":
                            okm = same_spk & diff_txt & (stt[:, None] != stt[None, :])
                        else:
                            okm = same_spk & diff_txt
                        Db = Q.boot_pair_median(
                            M, [(r["speaker"], r["state"], r["index"]) for r in items],
                            [(r["speaker"], r["state"]) for r in items], okm)
                    C, F_hi = c_ref(cal, e, setname, stratum)
                    lab, why, marker = label(Rb, Db, C, F_hi, stratum, det)
                    # SECTION 4: every aggregate is printed TWICE - pooled, and
                    # stratified by the support covariate. The stratified view
                    # NEVER assigns a label; support excludes nothing.
                    by_support = {}
                    for sup in sorted({str(r["support_mcd"]) for r in ok}):
                        sub = [r for r in ok if str(r["support_mcd"]) == sup]
                        sR = Q.boot_recording_median(
                            [r["R"] for r in sub],
                            [(r["speaker"], r["state"]) for r in sub],
                            [(r["speaker"], r["state"], r["index"]) for r in sub])
                        it2 = [r for r in sub if r["rec_emb_key"] in emb]
                        sD = {"refused": "NO ADMISSIBLE ITEMS"}
                        if len(it2) >= Q.MIN_RECORDINGS:
                            A2 = np.stack([emb[r["rec_emb_key"]] for r in it2]
                                          ).astype(np.float64)
                            M2 = A2 @ A2.T
                            s2 = np.array([r["speaker"] for r in it2])
                            t2 = np.array([r["state"] for r in it2])
                            x2 = np.array([r["index"] for r in it2])
                            ok2 = (s2[:, None] == s2[None, :]) & (x2[:, None] != x2[None, :])
                            if stratum == "CROSS":
                                ok2 &= (t2[:, None] != t2[None, :])
                            sD = Q.boot_pair_median(
                                M2, [(r["speaker"], r["state"], r["index"]) for r in it2],
                                [(r["speaker"], r["state"]) for r in it2], ok2)
                        by_support[sup] = {"n": len(sub), "R": sR, "D": sD,
                                           "label": "NOT ASSIGNED - SECTION 4 "
                                                    "stratified view, never a label"}
                    blk[stratum] = {
                        "R": Rb, "D": Db,
                        "C": (None if not C else {k: C[k] for k in
                                                  ("median", "lo", "hi",
                                                   "n_recordings", "refused")
                                                  if k in C}),
                        "F_hi": F_hi, "label": lab, "label_reason": why,
                        "marker": marker,
                        "n_cells": len(sel), "n_measured": len(ok),
                        "support_breakdown": dict(collections.Counter(
                            str(r["support_mcd"]) for r in sel)),
                        "by_support": by_support,
                    }
                res["arms"][arm][e]["sets"][setname] = blk

    # ------------------------------------------------ SECTION 6 duration analysis
    lens, len_files = length_states()
    res["length_state_lookup"] = {
        "files_read": len_files,
        "note": "SECTION 10.2: the covariate is read from every Stage 1 file at "
                "analysis time. The frozen measurement rows are NOT rewritten.",
        "rows_repaired_vs_row_value": sum(
            1 for r in rows if r["offline_length_state"] == "NOT RECORDED"
            and lens.get(r["key"]) is not None),
        "still_not_recorded": sum(
            1 for r in rows if lens.get(r["key"]) is None),
    }
    res["duration"] = {"cross_arm_rungs": [5.0, 10.0, 14.0],
                       "excluded": {
                           "1.0": "INADMISSIBLE everywhere (below the 2.00 s minimum)",
                           "2.0": "admissible in some arms and not others - realised "
                                  "output length spans 1.9199-2.0434 s, so the "
                                  "surviving arms are selected by an arm property. "
                                  "Reported per arm, never across arms."},
                       "arms": {}}
    for arm in arms:
        res["duration"]["arms"][arm] = {}
        for e in encs:
            per = {}
            for rung in (1.0, 2.0, 5.0, 10.0, 14.0):
                sel = [r for r in rows if r["arm"] == arm and r["encoder"] == e
                       and r["condition"] == "offline" and r["rung_s"] == rung]
                ok = [r for r in sel if r["cell_state"] == Q.MEASURED
                      and r["R"] is not None]
                texts = sorted({r["index"] for r in ok})
                per["%gs" % rung] = {
                    "n_cells": len(sel), "n_measured": len(ok),
                    "n_texts": len(texts),
                    "cross_arm_comparable": rung in (5.0, 10.0, 14.0),
                    "R": (Q.boot_recording_median(
                        [r["R"] for r in ok],
                        [(r["speaker"], r["state"]) for r in ok],
                        [(r["speaker"], r["state"], r["index"]) for r in ok])
                        if len(ok) >= Q.MIN_RECORDINGS else
                        {"refused": "TOO FEW ADMISSIBLE CELLS (%d)" % len(ok)}),
                }
            res["duration"]["arms"][arm][e] = per

    # ------------------------------------------------ SECTION 7 streamed detector
    idx = {(r["arm"], r["encoder"], r["key"]): r for r in rows
           if r["condition"] == "offline"}
    # SECTION 7: an arm that produced NO streamed output is NOT MEASURED, and
    # NOT MEASURED is a state that must be VISIBLE - never an arm quietly
    # missing from the table.
    streamed_arms = {r["arm"] for r in rows if r["condition"] == "streamed"}
    for arm in sorted(set(arms) - streamed_arms):
        res["streaming_detector"][arm] = {
            e: {"label": "NOT MEASURED - NO STREAMED OUTPUT",
                "S1_offline_vs_streamed_median": None,
                "S2_retention_delta_median": None,
                "n_paired": 0, "n_not_measured": 1736,
                "reason": "Gate 4 produced no streamed WAV for this arm "
                          "(<PRIVATE_STREAMED_ROOT> has no directory for it). "
                          "This is an absence of measurement, NEVER an absence "
                          "of effect."}
            for e in encs}
    for arm in sorted({r["arm"] for r in rows if r["condition"] == "streamed"}):
        res["streaming_detector"][arm] = {}
        for e in encs:
            s1, s2, miss = [], [], 0
            for r in [x for x in rows if x["condition"] == "streamed"
                      and x["arm"] == arm and x["encoder"] == e]:
                o = idx.get((arm, e, r["key"]))
                if not o or o["R"] is None or r["R"] is None:
                    miss += 1
                    continue
                if r["rec_emb_key"] in emb and o["rec_emb_key"] in emb:
                    s1.append(float(np.dot(emb[r["rec_emb_key"]].astype(np.float64),
                                           emb[o["rec_emb_key"]].astype(np.float64))))
                s2.append(r["R"] - o["R"])
            res["streaming_detector"][arm][e] = {
                "label": "DETECTOR - within-arm only; never a ranking, never a "
                         "SECTION 8 label",
                "S1_offline_vs_streamed_median": (float(np.median(s1)) if s1 else None),
                "S2_retention_delta_median": (float(np.median(s2)) if s2 else None),
                "n_paired": len(s2), "n_not_measured": miss}

    # ------------------------------------------------ encoder agreement, SECTION 8.6
    agree = {}
    for arm in arms:
        for setname in ("S", "L"):
            for stratum in (Q.STATES_S if setname == "S" else Q.STATES_L) + ["CROSS"]:
                labs = {e: res["arms"][arm][e]["sets"][setname][stratum]["label"]
                        for e in encs}
                c = collections.Counter(labs.values())
                top, n = c.most_common(1)[0]
                agree["%s|%s|%s" % (arm, setname, stratum)] = {
                    "labels": labs, "agreement": "%d/%d" % (n, len(encs)),
                    "dissenters": [e for e, l in labs.items() if l != top]}
    res["encoder_agreement"] = agree

    # SECTION 3 rule 4 / SECTION 8.2, added in revision 6: the reference and the
    # estimator must form the SAME pairs. Revision 5 silently differed by 3,255
    # (Set S) and 105 (Set L) same-script-line pairs. This is now checked, not
    # trusted: the calibration records what it admitted, and any mismatch is a
    # defect the report must not paper over.
    pair_check = {}
    for e in encs:
        for setname in ("S", "L"):
            cx = (cal["calibration"][e]["sets"][setname].get("cross") or {})
            ref_n = cx.get("n_pairs_admitted")
            ds = [res["arms"][a][e]["sets"][setname]["CROSS"]["D"].get("n_pairs")
                  for a in arms]
            ds = sorted({d for d in ds if d is not None})
            pair_check["%s|%s" % (e, setname)] = {
                "C_cross_pairs": ref_n, "D_cross_pairs_observed": ds,
                "match": bool(ref_n is not None and ds and all(d == ref_n for d in ds))}
    res["cross_pairing_check"] = pair_check
    bad = [k for k, v in pair_check.items() if not v["match"]]
    if bad:
        print("⛔ CROSS PAIRING MISMATCH (SECTION 3 rule 4): %s" % ", ".join(bad))
        for k in bad:
            print("   %s: C_cross=%s  D_cross=%s"
                  % (k, pair_check[k]["C_cross_pairs"],
                     pair_check[k]["D_cross_pairs_observed"]))
    else:
        print("cross pairing check: reference and estimator form identical pairs")
    json.dump(res, open(OUT, "w"), indent=1)
    print("wrote %s" % os.path.basename(OUT))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
